let UserUPN = tostring('{UPN}');
let InternalDomain = tostring(split(UserUPN,'@')[1]);
// --- Email: external recipients count
let ExtMail = toscalar(
    EmailEvents
    | where SenderFromAddress == UserUPN
    | extend RecipientDomain = tostring(split(RecipientEmailAddress,'@')[1])
    | where isnotempty(RecipientDomain) and RecipientDomain !~ InternalDomain
    | summarize c=count()
);
// --- Email: external attachments count
let ExtAttach = toscalar(
    EmailAttachmentInfo
    | join kind=inner (
        EmailEvents
        | where SenderFromAddress == UserUPN
    ) on NetworkMessageId
    | extend RecipientDomain = tostring(split(RecipientEmailAddress,'@')[1])
    | where isnotempty(RecipientDomain) and RecipientDomain !~ InternalDomain
    | summarize c=count()
);
// --- SharePoint/OneDrive downloads (OfficeActivity schema-safe)
let SPDownloads = toscalar(
    OfficeActivity
    | where UserId == UserUPN
    | extend WorkloadNorm = tostring(column_ifexists("OfficeWorkload", column_ifexists("Workload","")))
    | where WorkloadNorm in ("SharePoint","OneDrive")
    | summarize c=countif(Operation in ("FileDownloaded","FileSyncDownloadedFull","FileSyncDownloadedPartial"))
);
// --- Endpoint: local file creation proxy
let DeviceDownloads = toscalar(
    DeviceFileEvents
    | where InitiatingProcessAccountUpn == UserUPN
    | where ActionType == "FileCreated"
    | where FolderPath has_any ("\\Downloads\\","\\Desktop\\","\\Documents\\")
    | summarize c=count()
);
// --- Endpoint: USB copy proxy
let UsbCopy = toscalar(
    DeviceEvents
    | where InitiatingProcessAccountUpn == UserUPN
    | where ActionType in ("UsbDriveFileCopied","UsbDriveMounted")
    | summarize c=countif(ActionType == "UsbDriveFileCopied")
);
// --- Identity: unique IPs (schema-safe for UPN column)
let NewIPs = toscalar(
    SigninLogs
    | extend UPNNorm = tostring(column_ifexists("UserPrincipalName", column_ifexists("Identity","")))
    | where UPNNorm == UserUPN
    | where tobool(column_ifexists("IsInteractive", true)) == true
    | summarize c=dcount(tostring(column_ifexists("IPAddress", column_ifexists("IpAddress",""))))
);
// --- Identity: risky/failed sign-ins (schema-safe)
let RiskyOrFailed = toscalar(
    SigninLogs
    | extend UPNNorm = tostring(column_ifexists("UserPrincipalName", column_ifexists("Identity","")))
    | extend ResultTypeNorm = toint(column_ifexists("ResultType", 0))
    | extend RiskStateNorm  = tostring(column_ifexists("RiskState", "none"))
    | extend CAStatusNorm   = tostring(column_ifexists("ConditionalAccessStatus", ""))
    | where UPNNorm == UserUPN
    | where ResultTypeNorm != 0
        or RiskStateNorm != "none"
        or CAStatusNorm has_any ("failure","Failure")
    | summarize c=count()
);
// --- Cloud app activity (schema-safe)
let CloudApp = toscalar(
    CloudAppEvents
    | extend UPNNorm = tostring(column_ifexists("UserPrincipalName", column_ifexists("AccountDisplayName","")))
    | where UPNNorm == UserUPN
    | summarize c=count()
);
// --- Scoring
let Score_ExtMail = case(ExtMail >= 200, 100, ExtMail >= 50, 80, ExtMail >= 20, 60, ExtMail >= 6, 40, ExtMail >= 1, 20, 0);
let Score_ExtAttach = case(ExtAttach >= 50, 100, ExtAttach >= 20, 85, ExtAttach >= 6, 65, ExtAttach >= 1, 45, 0);
let Score_SPDownloads = case(SPDownloads >= 200, 100, SPDownloads >= 50, 80, SPDownloads >= 20, 60, SPDownloads >= 6, 40, SPDownloads >= 1, 20, 0);
let Score_DeviceDownloads = case(DeviceDownloads >= 500, 100, DeviceDownloads >= 200, 80, DeviceDownloads >= 50, 60, DeviceDownloads >= 10, 40, DeviceDownloads >= 1, 20, 0);
let Score_UsbCopy = case(UsbCopy >= 50, 100, UsbCopy >= 20, 85, UsbCopy >= 6, 65, UsbCopy >= 1, 55, 0);
let Score_NewIPs = case(NewIPs >= 20, 100, NewIPs >= 10, 75, NewIPs >= 5, 55, NewIPs >= 2, 35, NewIPs >= 1, 20, 0);
let Score_RiskyOrFailed = case(RiskyOrFailed >= 50, 100, RiskyOrFailed >= 20, 80, RiskyOrFailed >= 6, 60, RiskyOrFailed >= 1, 40, 0);
let Score_CloudApp = case(CloudApp >= 2000, 100, CloudApp >= 500, 75, CloudApp >= 200, 55, CloudApp >= 50, 35, CloudApp >= 1, 20, 0);
let OverallRiskScore = toint(round(
      0.05 * Score_ExtMail
    + 0.25 * Score_ExtAttach
    + 0.15 * Score_SPDownloads
    + 0.10 * Score_DeviceDownloads
    + 0.20 * Score_UsbCopy
    + 0.10 * Score_NewIPs
    + 0.10 * Score_RiskyOrFailed
    + 0.05 * Score_CloudApp
, 0));
let RiskBand = case(OverallRiskScore >= 75, "High", OverallRiskScore >= 40, "Medium", "Low");
print
    OverallRiskScore=OverallRiskScore,
    RiskBand=RiskBand,
    Score_ExtMail=Score_ExtMail,
    Score_ExtAttach=Score_ExtAttach,
    Score_SPDownloads=Score_SPDownloads,
    Score_DeviceDownloads=Score_DeviceDownloads,
    Score_UsbCopy=Score_UsbCopy,
    Score_NewIPs=Score_NewIPs,
    Score_RiskyOrFailed=Score_RiskyOrFailed,
    Score_CloudApp=Score_CloudApp
